function updateGuidance(){
  if(!scene)return;
  const region=activeRegion(),constraint=scene.constraints.find(item=>item.plane_id===activePlane),primary=$("#execute"),note=$("#note");
  if(!hasMeasuredHeight(scene)){
    primary.textContent="1 · Informe a altura";
    note.textContent="ALTURA OBRIGATÓRIA · meça do piso ao centro óptico da câmera";
  }else if(!hasHorizontalAlignmentEvidence(scene)){
    primary.textContent=alignmentMode==="assisted"?"2 · Escolha uma proposta":"2 · Marque o alinhamento";
    note.textContent=alignmentMode==="assisted"?"DESCUBERTA ASSISTIDA · selecione bundles, crie um plano e aceite-o como piso":"ALINHE O PISO · marque 2 retas A + 2 retas B, ou 2 pontos de fuga";
  }else if(!orientationAccepted()){
    primary.textContent="2 · Validar alinhamento";
    note.textContent="EVIDÊNCIA PRONTA · valide o frame horizontal antes de segmentar";
  }else if(region?.interpretation==="seed"){
    primary.textContent=activePlane==="floor"?"3 · Segmentar piso":"3 · Segmentar plano";
    note.textContent="ALINHAMENTO ACEITO · agora a segmentação pode começar";
  }else if(region?.state!=="accepted"){
    primary.textContent="3 · Aceitar máscara";
    note.textContent="PROPOSTA PRONTA · revise o amarelo e aceite a máscara";
  }else if(constraint?.state!=="accepted"){
    primary.textContent=constraint?.kind==="floor-anchor"?"4 · Confirmar piso":"4 · Confirmar relação";
    note.textContent=constraint?.kind==="floor-anchor"?"MÁSCARA ACEITA · confirme que esta região é o piso":"MÁSCARA ACEITA · marque o contato e confirme a relação";
  }else if(currentRun.status!=="completed"||Number(currentRun.metrics.valid_range_pixels??0)===0){
    primary.textContent="4 · Gerar mapa métrico";
    note.textContent="RELAÇÃO CONFIRMADA · execute a revisão para publicar range";
  }else{
    primary.textContent="+ Adicionar outro plano";
    note.textContent=`MAPA ATUAL · ${currentRun.metrics.resolved_planes??0} plano(s) resolvido(s) · explore em 2D ou 3D`;
  }
}
async function advance(){
  const region=activeRegion(),constraint=scene?.constraints.find(item=>item.plane_id===activePlane);
  if(!scene||!hasMeasuredHeight(scene)){status.textContent="Informe a altura medida do centro óptico ao piso";$("#height").focus();return}
  if(!hasHorizontalAlignmentEvidence(scene)){status.textContent=alignmentMode==="assisted"?"Selecione ao menos dois bundles e use uma proposta como piso":"Marque duas retas na família A e duas na B, ou dois pontos de fuga";return}
  if(!orientationAccepted()){await execute(true);return}
  if(region?.interpretation==="seed"){await execute(false);return}
  if(region?.state!=="accepted"){acceptMask();return}
  if(constraint?.state!=="accepted"){confirmRelation();return}
  if(currentRun.status==="completed"&&Number(currentRun.metrics.valid_range_pixels??0)>0){addPlane();return}
  await execute();
}
