document.querySelectorAll<HTMLButtonElement>("[data-alignment-mode]").forEach(button=>button.onclick=()=>{alignmentMode=button.dataset.alignmentMode as "assisted"|"manual";document.querySelectorAll<HTMLButtonElement>("[data-alignment-mode]").forEach(item=>item.classList.toggle("active",item.dataset.alignmentMode===alignmentMode));alignmentProjection=alignmentMode==="assisted"?"erp":"gnomonic";imageTools.setToolLabel("projection",alignmentProjection==="gnomonic"?"Mostrar ERP":"Mostrar gnomônica",alignmentProjection==="gnomonic"?"Alternar para contexto ERP":"Voltar à carta gnomônica");if(alignmentMode==="assisted"&&!discoveryResult&&!discoveryBusy)void runPlanarDiscovery().catch(error=>status.textContent=`Descoberta indisponível · ${error.message}`);renderAll()});
$("#discoverScene").onclick=()=>void runPlanarDiscovery().catch(error=>status.textContent=`Descoberta indisponível · ${error.message}`);
$("#toggleDiscoveryLines").onclick=()=>{if(!discoveryResult||!selectedDiscoveryLines.size)return;const selected=[...selectedDiscoveryLines],restore=selected.some(id=>discoveryResult!.lines.find(line=>line.line_id===id)?.state==="rejected");for(const id of selected)discoveryLineDecisions[id]=restore?"accepted":"rejected";selectedDiscoveryLines.clear();void runPlanarDiscovery().catch(error=>status.textContent=`Revisão indisponível · ${error.message}`)};
$("#makeDiscoveryBundle").onclick=()=>{if(selectedDiscoveryLines.size<2)return;const id=`human-bundle-${Object.keys(discoveryBundleMemberships).length+1}`;discoveryBundleMemberships[id]=[...selectedDiscoveryLines].sort();selectedDiscoveryLines.clear();void runPlanarDiscovery().catch(error=>status.textContent=`Bundle inválido · ${error.message}`)};
$("#assignLines").onclick=()=>{if(selectedDiscoveryLines.size<2)return;discoveryPlaneLineGroups[activePlane]=[...selectedDiscoveryLines].sort();selectedDiscoveryLines.clear();void runPlanarDiscovery().catch(error=>status.textContent=`Associação inválida · ${error.message}`)};
$("#makeDiscoveryPlane").onclick=()=>{if(selectedDiscoveryBundles.size<2)return;discoveryPlaneGroups[`orientation-${activePlane}`]=[...selectedDiscoveryBundles].sort();selectedDiscoveryBundles.clear();void runPlanarDiscovery().catch(error=>status.textContent=`Orientação inválida · ${error.message}`)};
$("#guidedClearLines").onclick=()=>{selectedDiscoveryLines.clear();guidedPhase="lines";renderDiscovery();renderGuidedDiscovery();draw()};
$("#guidedSelectLines").onclick=()=>{selectTool("navigate");status.textContent=`Seleção de retas de ${activeRegion()?.label??activePlane} · clique nas retas ou use Shift + arraste`};
$("#guidedDrawLine").onclick=()=>{selectTool("line");status.textContent=`Desenhe uma reta ausente de ${activeRegion()?.label??activePlane} na carta gnomônica`};
$("#guidedAssociateLines").onclick=()=>{if(!selectedDiscoveryLines.size)return;const count=selectedDiscoveryLines.size,members=new Set(discoveryPlaneLineGroups[activePlane]??[]);for(const id of selectedDiscoveryLines)members.add(id);discoveryPlaneLineGroups[activePlane]=[...members].sort();guidedPhase="directions";selectTool("navigate");status.textContent=`${count} reta${count===1?"":"s"} associada${count===1?"":"s"} a ${activeRegion()?.label??activePlane} · agora selecione paralelas e crie uma direção`;void runPlanarDiscovery().catch(error=>status.textContent=`Associação inválida · ${error.message}`)};
$("#guidedEstimateDirection").onclick=()=>{const state=guidedLineEvidenceActions(selectedDiscoveryLines,discoveryPlaneLineGroups[activePlane]??[]);if(!state.canEstimateDirection)return;const id=`human-bundle-${Object.keys(discoveryBundleMemberships).length+1}`;discoveryBundleMemberships[id]=[...selectedDiscoveryLines].sort();selectedDiscoveryLines.clear();selectedDiscoveryBundles.add(id);expandedDirectionId=id;guidedPhase="expand";status.textContent="Estimando a fuga da nova direção e procurando retas semelhantes…";void runPlanarDiscovery().catch(error=>status.textContent=`Direção inválida · ${error.message}`)};
$("#guidedCreateOrientation").onclick=()=>{if(selectedDiscoveryBundles.size<2)return;const matching=findMatchingOrientationProposal(discoveryResult?.proposals??[],selectedDiscoveryBundles);if(matching){guidedPhase="orientation";status.textContent=`Orientação calculada para ${activeRegion()?.label??activePlane} · revise e aceite`;renderGuidedDiscovery();return}discoveryPlaneGroups[`orientation-${activePlane}`]=[...selectedDiscoveryBundles].sort();status.textContent=`Combinando ${selectedDiscoveryBundles.size} direções para orientar ${activeRegion()?.label??activePlane}…`;void runPlanarDiscovery().catch(error=>status.textContent=`Orientação inválida · ${error.message}`)};
$("#discoveryDensity").onchange=()=>{const value=$("#discoveryDensity").value;if(value==="custom")return;setDiscoveryControls(planarDiscoveryPreset(value as DiscoveryPresetName));resetDiscovery();status.textContent="Preset alterado · revisões automáticas reiniciadas";void runPlanarDiscovery().catch(error=>status.textContent=`Descoberta indisponível · ${error.message}`)};
function markDiscoveryTuningChanged(){const tuning=currentDiscoveryTuning(),custom=document.querySelector<HTMLOptionElement>('#discoveryDensity option[value="custom"]')!;custom.disabled=false;$("#discoveryDensity").value="custom";setDiscoveryControls(tuning);resetDiscovery();renderDiscovery();draw();status.textContent=`Configuração alterada · ${tuning.atlasFaceSize}² por carta · clique Detectar cena`}
for(const id of ["#discoveryFaceSize","#discoveryCannyLow","#discoveryCannyHigh","#discoveryLocalContrast","#discoveryMinSegment","#discoveryEdgeSupport"])$(id).addEventListener("change",markDiscoveryTuningChanged);
window.addEventListener("keydown",event=>{if(event.key!=="Escape")return;alignmentDrag=null;pendingViewLine=null;adjustPreview=null;if(pendingPointReview){decidePointAdjustment("manual");return}pointAdjustment=null;imageTools.setReadout(null);draw();status.textContent="Marcação atual cancelada"});
$("#sample").textContent="Recarregar imagem padrão";
$("#sample").onclick=()=>{currentRun={} as Run;void loadSample(false)};
$("#reference").onclick=()=>{currentRun={} as Run;void loadSample(true)};
$("#execute").onclick=()=>void advance().catch(error=>{status.textContent=`Falha · ${error.message}`;status.classList.add("kh-error")});
setDiscoveryControls(discoveryTuning);
renderSamResource();
void fetch("/api/v1/capabilities").then(r=>r.json()).then(v=>$("#runtime").textContent=`PanorAi ${v.panorai_version??"local"}`);void loadSample(false).catch(e=>status.textContent=`Amostra indisponível · ${e.message}`);
